
%% currentDayConditions 
% Function returns condition rotations for today (currently just for valve /stimuli assignments). 

% true  = odor
% false = water
%
% startDate     : datetime of first experiment day (optional after first call)
% startingOrder : starting valve assignments, 1x4 array with valve numbers so that the 
%                 first two are stim1 and the second two are stim2 (e.g. [2 3 5 6])
% 
% After first call, save startDate and startingOrder to file: 'startingStimRotations.mat' 
% in the Calibration Files folder.

% Original script generated by DeepSeek. Modified, validated, and integrated by TVD. 

function [stim1_valves, stim2_valves, currentStartOrder] = currentDayConditions(startDate, startingOrder)
    
    %% Get/Set starting date and starting stimulus valve order
    
    % Load saved starting date and starting valve order
    configFile = fullfile(fileparts(which('startingStimRotations.mat')), 'startingStimRotations.mat');
    if isfile(configFile)
        S                        = load(configFile);
        savedStartDate           = S.saved.startDate; 
        savedStartingStimColumns = S.saved.startingOrder; 
    else % <-- first-ever defaults
        if nargin < 1 || isempty(startDate) 
            startDate = datetime(2026,9,29);
        end
        if nargin < 2 || isempty(startingOrder) 
            startingOrder = [2 3 5 6]; % water water, odor odor
        end

        savedStartDate           = startDate;
        savedStartingStimColumns = startingOrder;
    end

    % Subsequent calls: allow explicit overrides, otherwise reuse saved.
    if nargin >= 1 && ~isempty(startDate)
        savedStartDate = startDate;
    end
    if nargin >= 2 && ~isempty(startingOrder)
        savedStartingStimColumns = startingOrder;
    end

    %% Run
    N = length(savedStartingStimColumns);
    dayNum = floor(days(datetime('today') - savedStartDate)); % 0 on first day

    if mod(N,2) ~= 0; error('N must be even to have equal numbers in both states.'); end
    if dayNum < 0; error('Start date is in the future.'); end

    condRotation = conditionsForDay(dayNum, N);
    
    stim1_valves = savedStartingStimColumns(~condRotation); 
    stim2_valves = savedStartingStimColumns(condRotation); 
    currentStartOrder = savedStartingStimColumns; 
    
    % Save config (starting date and order)
    saved.startDate      = savedStartDate;
    saved.startingOrder = savedStartingStimColumns;
    save(configFile, 'saved');

    %disp(['Water valves: [', num2str(waterValves), '] Odor valves: [', num2str(odorValves), ']']);
end

function condRotation = conditionsForDay(dayNum, N)
    % Core rotation. dayNum can be any integer day counter.

    if mod(N,2) ~= 0
        error('N must be even.');
    end

    base = [false(1, N/2), true(1, N/2)];   % first day: N/2 stim1, N/2 stim2
    idx  = mod((0:N-1) - dayNum, N) + 1;    % rotate by one each day
    condRotation = base(idx);
end